const tz = 'Europe/Istanbul';

function formatInTz(date) {
  const parts = new Intl.DateTimeFormat('en-CA', {
    timeZone: tz,
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
  }).formatToParts(date);
  const get = (t) => parts.find((p) => p.type === t).value;
  return { year: get('year'), month: get('month'), day: get('day') };
}

const now = new Date();
const today = formatInTz(now);
const yesterdayInstant = new Date(now.getTime() - 24 * 60 * 60 * 1000);
const yesterday = formatInTz(yesterdayInstant);

const toEpdk = (p) => `${p.day}.${p.month}.${p.year}`;
const toIso = (p) => `${p.year}-${p.month}-${p.day}`;

return [{
  json: {
    today_epdk: toEpdk(today),
    today_iso: toIso(today),
    yesterday_epdk: toEpdk(yesterday),
    yesterday_iso: toIso(yesterday),
    prepared_at: now.toISOString(),
  },
}];

const res = $input.first().json;
const dates = $('Prepare Report Date').first().json;

if (res.error) {
  throw new Error(`EPDK istegi basarisiz (retry sonrasi): ${typeof res.error === 'string' ? res.error : JSON.stringify(res.error)}`);
}

const httpStatus = res.statusCode || 0;
let body = res.body;
if (typeof body === 'string') {
  try {
    body = JSON.parse(body);
  } catch (e) {
    throw new Error(`EPDK yaniti JSON olarak ayristirilamadi (HTTP ${httpStatus}): ${body.slice(0, 200)}`);
  }
}
body = body || {};

if (!httpStatus) {
  throw new Error('EPDK API ulasilamadi (baglanti hatasi / timeout).');
}

if (body.fault) {
  throw new Error(`EPDK API gateway hatasi: ${body.fault.faultString || JSON.stringify(body.fault)} (HTTP ${body.fault.faultStatusCode || httpStatus})`);
}

if (httpStatus >= 400) {
  throw new Error(`EPDK API beklenmeyen HTTP ${httpStatus} dondurdu: ${JSON.stringify(body).slice(0, 300)}`);
}

if (body.statusCode !== 200) {
  throw new Error(`EPDK statusCode basarisiz: ${body.statusCode} - ${body.statusDescription || body.message || ''}`);
}

if (Array.isArray(body.errors) && body.errors.length > 0) {
  throw new Error(`EPDK errors alani dolu: ${JSON.stringify(body.errors)}`);
}

if (!Array.isArray(body.data)) {
  throw new Error('EPDK yanitinda data alani array degil - response semasi degismis olabilir.');
}

const hasData = body.data.length > 0;

return [{
  json: {
    hasData,
    numRows: typeof body.numRows === 'number' ? body.numRows : body.data.length,
    data: body.data,
    requestedDate: dates.today_epdk,
    attempt: 'today',
  },
}];

const res = $input.first().json;
const dates = $('Prepare Report Date').first().json;

if (res.error) {
  throw new Error(`EPDK istegi basarisiz (retry sonrasi, fallback): ${typeof res.error === 'string' ? res.error : JSON.stringify(res.error)}`);
}

const httpStatus = res.statusCode || 0;
let body = res.body;
if (typeof body === 'string') {
  try {
    body = JSON.parse(body);
  } catch (e) {
    throw new Error(`EPDK yaniti JSON olarak ayristirilamadi (HTTP ${httpStatus}, fallback): ${body.slice(0, 200)}`);
  }
}
body = body || {};

if (!httpStatus) {
  throw new Error('EPDK API ulasilamadi (baglanti hatasi / timeout, fallback denemesi).');
}

if (body.fault) {
  throw new Error(`EPDK API gateway hatasi (fallback): ${body.fault.faultString || JSON.stringify(body.fault)} (HTTP ${body.fault.faultStatusCode || httpStatus})`);
}

if (httpStatus >= 400) {
  throw new Error(`EPDK API beklenmeyen HTTP ${httpStatus} dondurdu (fallback): ${JSON.stringify(body).slice(0, 300)}`);
}

if (body.statusCode !== 200) {
  throw new Error(`EPDK statusCode basarisiz (fallback): ${body.statusCode} - ${body.statusDescription || body.message || ''}`);
}

if (Array.isArray(body.errors) && body.errors.length > 0) {
  throw new Error(`EPDK errors alani dolu (fallback): ${JSON.stringify(body.errors)}`);
}

if (!Array.isArray(body.data)) {
  throw new Error('EPDK yanitinda data alani array degil (fallback) - response semasi degismis olabilir.');
}

const hasData = body.data.length > 0;

if (!hasData) {
  const todayStr = $('Prepare Report Date').first().json.today_epdk;
  const yesterdayStr = dates.yesterday_epdk;
  throw new Error(
    `EPDK bulteni ne bugun (${todayStr}) ne dun (${yesterdayStr}) icin yayinlanmis. ` +
    'Muhtemelen bugunku bulten henuz hazir degil; bir sonraki zamanlanmis calismada tekrar denenecek.'
  );
}

return [{
  json: {
    hasData: true,
    numRows: typeof body.numRows === 'number' ? body.numRows : body.data.length,
    data: body.data,
    requestedDate: dates.yesterday_epdk,
    attempt: 'fallback_yesterday',
  },
}];

const input = $input.first().json;
const rows = Array.isArray(input.data) ? input.data : [];

// EPDK'nin gercek "Yakit" degerleri (2026-09-13 dogrulandi). Yalnizca filoyla
// ilgili urunler eslesiyor. Otogaz/LPG bu bultende hic gorulmedi; ileride
// gorulursa diye olasi isimler eklendi ama dogrulanmadan varsayilmadi.
const FUEL_MAP = {
  'Kurşunsuz Benzin 95 Oktan': 'gasoline',
  'Motorin': 'diesel',
  'Otogaz (LPG)': 'lpg',
  'LPG': 'lpg',
};

// Bilinen ama filo icin ilgisiz urunler (endustriyel/isinma yakiti) - hata
// degil, sessiz de degil: sayilir ve loglanir, gasoline/diesel/lpg'ye asla
// yanlis map edilmez.
const KNOWN_IRRELEVANT = new Set([
  "Yüksek Kükürtlü Fuel Oil (Kükürt oranı %1'i geçenler)",
  'Kalorifer Yakıtı (Kükürt Oranı %0.1\'i geçen ancak %1\'i geçmeyenler)',
  'Gazyağı',
  'Fuel Oil (Kükürt Oranı %0.1\'i geçen ancak %1\'i geçmeyenler)',
]);

const mapped = [];
const unmapped = [];
let ignoredCount = 0;

for (const row of rows) {
  const fuelName = String(row['Yakıt'] ?? '').trim();
  const fuelType = FUEL_MAP[fuelName];

  if (!fuelType) {
    if (KNOWN_IRRELEVANT.has(fuelName)) {
      ignoredCount += 1;
    } else {
      unmapped.push(fuelName);
    }
    continue;
  }

  const rawPrice = row['Fiyat'];
  const price = typeof rawPrice === 'number' ? rawPrice : parseFloat(String(rawPrice ?? '').replace(',', '.'));
  const priceDate = String(row['Tarih'] ?? '').trim();
  const unit = String(row['Ölçü Birimi'] ?? '').trim();

  mapped.push({
    price_date: priceDate,
    fuel_type: fuelType,
    fuel_name: fuelName,
    unit,
    price,
    source: 'EPDK',
    fetched_at: new Date().toISOString(),
  });
}

const meta = {
  _requestedDate: input.requestedDate,
  _attempt: input.attempt,
  _unmapped: unmapped,
  _ignoredCount: ignoredCount,
  _totalSeen: rows.length,
};

if (mapped.length === 0) {
  return [{ json: { _placeholder: true, ...meta } }];
}

return mapped.map((row) => ({ json: { ...row, ...meta } }));

const items = $input.all().map((i) => i.json);

const VALID_TYPES = new Set(['gasoline', 'diesel', 'lpg']);
const seen = new Map();
const rejected = [];

for (const it of items) {
  if (it._placeholder) continue;

  const priceOk = typeof it.price === 'number' && Number.isFinite(it.price) && it.price > 0;
  const dateOk = /^\d{4}-\d{2}-\d{2}$/.test(it.price_date || '');
  const typeOk = VALID_TYPES.has(it.fuel_type);

  if (!priceOk || !dateOk || !typeOk) {
    rejected.push({
      fuel_name: it.fuel_name,
      fuel_type: it.fuel_type,
      price: it.price,
      price_date: it.price_date,
      reason: !typeOk ? 'invalid_fuel_type' : !dateOk ? 'invalid_price_date' : 'invalid_price',
    });
    continue;
  }

  // Ayni fuel_type ayni partide iki kez gelirse ilkini koru (savunma amacli;
  // EPDK'da tek tarih icin tek satir/urun gorulduyor).
  if (!seen.has(it.fuel_type)) {
    seen.set(it.fuel_type, {
      price_date: it.price_date,
      fuel_type: it.fuel_type,
      fuel_name: it.fuel_name,
      unit: it.unit,
      price: Math.round(it.price * 100000) / 100000,
      source: it.source,
      fetched_at: it.fetched_at,
    });
  }
}

const rows = [...seen.values()];
const first = items[0] || {};

if (rows.length === 0) {
  throw new Error(
    `Normalize sonrasi hic gecerli gasoline/diesel/lpg fiyati kalmadi ` +
    `(gorulen ham satir: ${first._totalSeen ?? 0}, eslenemeyen: ${JSON.stringify(first._unmapped ?? [])}, reddedilen: ${JSON.stringify(rejected)}).`
  );
}

return [{
  json: {
    rows,
    row_count: rows.length,
    requested_date: first._requestedDate,
    attempt: first._attempt,
    unmapped_fuel_types: first._unmapped ?? [],
    ignored_irrelevant_count: first._ignoredCount ?? 0,
    rejected,
  },
}];

const res = $input.first().json;
const prior = $('Validate Fuel Prices').first().json;

if (res.error) {
  throw new Error(`Supabase upsert basarisiz (retry sonrasi): ${typeof res.error === 'string' ? res.error : JSON.stringify(res.error)}`);
}

const httpStatus = res.statusCode || 0;
let body = res.body;
if (typeof body === 'string') {
  try {
    body = JSON.parse(body);
  } catch (e) {
    body = null;
  }
}

if (httpStatus < 200 || httpStatus >= 300) {
  throw new Error(`Supabase upsert basarisiz (HTTP ${httpStatus}): ${JSON.stringify(body).slice(0, 500)}`);
}

const written = Array.isArray(body) ? body.length : null;

return [{
  json: {
    ok: true,
    requested_date: prior.requested_date,
    attempt: prior.attempt,
    rows_sent: prior.row_count,
    rows_written: written,
    fuel_types: prior.rows.map((r) => r.fuel_type),
    unmapped_fuel_types: prior.unmapped_fuel_types,
    ignored_irrelevant_count: prior.ignored_irrelevant_count,
  },
}];
